  const todos = load(path);
  switch (cmd.kind) {
    case "add": {
      const next = add(todos, cmd.title, cmd.due);
      save(path, next);
      return `Added #${next[next.length - 1].id}`;
    }
    case "complete":
      save(path, complete(todos, cmd.id));
      return `Completed #${cmd.id}`;
    case "clear": {
      const next = clear(todos);
      save(path, next);
      const removed = todos.length - next.length;
      return `Cleared ${removed} completed ${removed === 1 ? "todo" : "todos"}`;
    }
    case "list":
      return list(todos);
